  font-style: normal;
  font-display: swap;
}

@font-face {
  font-family: "Shabnam FD";
  src: url("./Shabnam-FD.woff2") format("woff2");
  font-weight: 400;
  font-style: normal;
  font-display: swap;
}

@font-face {
  font-family: "Shabnam FD";
